import { zoned } from "../hooks/useSafeTimezone";
const STATE = {
    CUSTOM: "CUSTOM",
    PRESET: "PRESET",
};
const ACTION = {
    CANCEL: "CANCEL",
    CHANGE_CURRENT_VALUE: "CHANGE_CURRENT_VALUE",
    CHANGE_TAB: "CHANGE_TAB",
    RESET: "RESET",
    SET_END_TO_NOW: "SET_END_TO_NOW",
    SUBMIT: "SUBMIT",
};
const DEFAULT_TABS = [STATE.PRESET, STATE.CUSTOM];
const getNow = (timezone) => zoned(Date.now(), timezone).millisecond(0);
const getAvailableTabsForConfig = (tabs) => {
    const validTabs = tabs
        ?.map((tab) => tab?.toUpperCase())
        .filter((tab) => DEFAULT_TABS.includes(tab))
        .slice(0, 2);
    if (!validTabs?.length) {
        return DEFAULT_TABS;
    }
    return validTabs;
};
const getInitialTab = (tabs, value) => {
    if (tabs.length === 1) {
        return tabs[0];
    }
    if (value && "timeFrame" in value && typeof value.timeFrame === "string") {
        return STATE.PRESET;
    }
    if (value && "from" in value && "to" in value) {
        return STATE.CUSTOM;
    }
    return tabs[0];
};
const createInitialState = ({ tabs, timezone, value, }) => {
    const availableTabs = getAvailableTabsForConfig(tabs);
    const now = getNow(timezone);
    const initialTab = getInitialTab(availableTabs, value);
    if (initialTab === STATE.PRESET) {
        return {
            availableTabs,
            currentCustomValue: [null, null],
            currentTimeFrameValue: { timeFrame: value?.timeFrame ?? "" },
            isDirty: false,
            now,
            state: STATE.PRESET,
        };
    }
    return {
        availableTabs,
        currentCustomValue: value && "from" in value && "to" in value
            ? [
                zoned(value.from, timezone),
                zoned(value.to, timezone),
            ]
            : [null, null],
        currentTimeFrameValue: { timeFrame: "" },
        isDirty: false,
        now,
        state: STATE.CUSTOM,
    };
};
const getMergedState = (state) => (_, lastStage) => ({
    ...lastStage,
    state,
});
const getChangeCustomValueState = ({ newValue, timezone }, lastStage) => ({
    ...lastStage,
    currentCustomValue: newValue,
    isDirty: true,
    now: getNow(timezone),
});
const getChangeTimeFrameValueState = ({ newValue, timezone }, lastStage) => ({
    ...lastStage,
    currentTimeFrameValue: newValue,
    isDirty: true,
    now: getNow(timezone),
});
const getCancelState = ({ initialValue, timezone }, lastStage) => {
    const stage = createInitialState({
        timezone: timezone,
        value: initialValue,
    });
    return {
        ...stage,
        availableTabs: lastStage.availableTabs,
        isDirty: false,
    };
};
const getSubmitState = (_, lastStage) => {
    if (lastStage.state === STATE.CUSTOM) {
        return {
            ...lastStage,
            currentTimeFrameValue: { timeFrame: "" },
            isDirty: false,
        };
    }
    return {
        ...lastStage,
        currentCustomValue: [null, null],
        isDirty: false,
    };
};
const getResetState = ({ initialValue, timezone }, lastStage) => ({
    ...lastStage,
    currentCustomValue: initialValue && !("timeFrame" in initialValue)
        ? [
            zoned(initialValue?.from, timezone),
            zoned(initialValue?.to, timezone),
        ]
        : [null, null],
});
const getSetEndDateToNowState = ({ newValue, timezone }, lastStage) => {
    const now = getNow(timezone);
    return {
        ...lastStage,
        currentCustomValue: [newValue[0], now],
        now,
    };
};
const NEXT_STATE_GRAPH = {
    [STATE.CUSTOM]: {
        [ACTION.CANCEL]: getCancelState,
        [ACTION.CHANGE_CURRENT_VALUE]: getChangeCustomValueState,
        [ACTION.CHANGE_TAB]: getMergedState(STATE.PRESET),
        [ACTION.SET_END_TO_NOW]: getSetEndDateToNowState,
        [ACTION.SUBMIT]: getSubmitState,
        [ACTION.RESET]: getResetState,
    },
    [STATE.PRESET]: {
        [ACTION.CANCEL]: getCancelState,
        [ACTION.CHANGE_CURRENT_VALUE]: getChangeTimeFrameValueState,
        [ACTION.CHANGE_TAB]: getMergedState(STATE.CUSTOM),
        [ACTION.SET_END_TO_NOW]: getSetEndDateToNowState,
        [ACTION.SUBMIT]: getSubmitState,
    },
};
const reducer = (lastStage, event) => {
    const nextStageBuilder = NEXT_STATE_GRAPH[lastStage.state]?.[event.type];
    return nextStageBuilder !== undefined
        ? nextStageBuilder(event, lastStage)
        : lastStage;
};
export { ACTION, STATE, reducer, createInitialState };
